// tracker-adapter.js — read Builder-bot's per-verse stage document and hand it to the dots map. Read-only.
//
// Chief of Staff (15 Nov): the Verse map tracks ONLY new verse-by-verse recordings and starts empty. The old red/green marks
// (v7 snapshot, 'bible-coverage-tracker.v2', Firebase /t/<sha256('bible-coverage-tracker.sync.v1:'+code)>) are NOT mapped
// onto the map; they stay exactly as they are in the Tracker's existing tabs.
// Builder-bot (INTERFACES-BUILDER.md C2): the per-verse document lives in a SEPARATE slot, written only by Builder-bot's stages.js:
//   localStorage 'bible-coverage-tracker.vbv.stages.v1', Firebase /t/<sha256('bible-coverage-tracker.vbv.v1:'+code)>.json.
//   stages.js owns the local/cloud merge. This file only picks local-else-cloud as a fallback and reads per-verse stages:
//   nothing is spread from chapters onto verses (Builder-bot's records arrive per verse).

const VBV_KEY = 'bible-coverage-tracker.vbv.stages.v1';      // INTERFACES-BUILDER C2 (Builder-bot owns it)
const VBV_SLOT_PREFIX = 'bible-coverage-tracker.vbv.v1:';     // slot = sha256(prefix + save code), under /t/

/** Local document if present, else the cloud copy (fallback only; the real merge is stages.js's job). */
function chooseVbvDoc(localDoc, cloudDoc) { return localDoc || cloudDoc || null; }

/** doc = { app:'bible-coverage-tracker.vbv', version:1, verses:{ "GEN-6": { "v19": {st, at, sha256, drive_id, gate, rev} } },
 *          units:{ "Genesis 6": {st, at, restitch, video:{status, visibility, at, reason}} } }
 *  -> { stages: Uint8Array(31102) from each verse record's st (0-4), units: the unit records as given (words only), bad,
 *       last: verse id of the most recent activity (latest `at` among recorded verses; a tie goes to the later verse), lastAt }.
 *  No doc -> every verse 0 (the map starts empty). */
function stagesFromVbvDoc(doc) {
  const stages = new Uint8Array(TOTAL); let bad = 0, lastT = -Infinity, lastG = -1; // v7: "last worked on" = latest `at`; tie -> later verse

  const d = typeof doc === 'string' ? JSON.parse(doc) : (doc || {});
  const V = d.verses || {};
  for (const ck in V) { const m = /^([1-3A-Z]{3})-(\d+)$/.exec(ck); if (!m) { bad++; continue; }
    for (const vk in V[ck]) { const g = verseIndex(m[1] + '.' + m[2] + '.' + String(vk).replace(/^v/, '')); if (g < 0) { bad++; continue; }
      const rec = V[ck][vk] || {}, st = +rec.st || 0; stages[g] = st >= 0 && st <= 4 ? st : 0;
      const t = typeof rec.at === 'number' ? rec.at : Date.parse(rec.at || ''); if (st > 0 && t === t && (t > lastT || (t === lastT && g > lastG))) { lastT = t; lastG = g; } } }
  return { stages, units: Object.assign({}, d.units || {}), bad, last: lastG >= 0 ? verseId(lastG) : null, lastAt: lastG >= 0 ? lastT : null };
}

/** Same-origin convenience: read the local document (read-only) and fall back to a cloud copy the host already fetched. */
function readVbvLocalStorage(ls = window.localStorage, cloudDoc = null) {
  let local = null; try { const r = ls.getItem(VBV_KEY); local = r ? JSON.parse(r) : null; } catch (e) { /* private mode or unreadable */ }
  return stagesFromVbvDoc(chooseVbvDoc(local, cloudDoc));
}

